const Sequelize = require("sequelize");
const db = require("../models");
const InsertProduct = require("../dtos/requests/order/InsertOrder")
const UpdateOrder = require("../dtos/requests/order/UpdateOrder");
const Op = Sequelize.Op;
const {OrderStatus} = require('../constants')


async function getOrders(req, res) {
  const { search = "", page = 1 , status} = req.query;

  const pageSize = 5;

  const offset = (page - 1) * pageSize;

  let whereClause = {};

  if (search.trim() !== "") {
    whereClause = {
      [Op.or]: [
        { note: { [Op.like]: `%${search}%` } }
      ],
    };
  }
  if(status){
    whereClause.status = status
  }
  const [orders, totalOrders] = await Promise.all([
    db.orders.findAll({
      where: whereClause,
      limit: pageSize,
      offset: offset,
      order: [['created_at', 'DESC']]
    }),

    db.orders.count({
      where: whereClause,
    }),
  ]);

  res.status(200).json({
    message: "Lấy danh sách đơn hàng thành công",
    data: orders,
    currentPage: page,
    totalPages: Math.ceil(totalOrders / pageSize),
    totalOrders,
  });
}

async function getOrderById(req, res) {
  const { id } = req.params;

  const order = await db.orders.findByPk(id, {
    include: [
      {
        model: db.order_detail,
        as: 'order_detail'
      },
    ],
  });

  if (!order) {
    return res.status(404).json({
      message: "không tìm thấy đơn hàng",
    });
  }

  return res.status(200).json({
    message: "lấy đơn hàng thành công",
    data: order,
  });
}


/*async function insertOrder(req, res) {
  const userId = req.body.user_id
  const user = await db.users.findByPk(userId)
  if(!user){
    return res.status(404).json({
      message: "user ko tồn tại"
    })
  }
  const order = await db.orders.create(req.body);
  console.log("Thêm đơn hàng thành công:", order.toJSON());
  return res.status(200).json({
    message: "Thêm mới đơn hàng thành công",
    data: order,
  });
}
*/
async function deleteOrder(req, res) {
  const { id } = req.params;
  console.log(OrderStatus.FAILED);

  // this is soft delete,
  // update order.status = OrderStatus.FAILED
 // cập nhật trạng thái đơn hàn g sang FAILED  thay vì xóa
  const [update] = await db.orders.update({status: OrderStatus.FAILED}, {
    where: { id },
  });

  if (update) {
    return res.status(200).json({
      message: "xóa mềm",
    });
  }
  return res.status(404).json({
    message: "đơn hàng không tồn tại",
  });
}

async function updateOrder(req, res) {

    const { id } = req.params;

    const [updated] = await db.orders.update(req.body, {
        where: { id },
    });

    if (updated) {

        return res.status(200).json({
            message: "Cập nhật đơn hàng thành công",
        });
    }

    return res.status(404).json({
        message: "Đơn hàng không tồn tại",
    });
}

module.exports = {
  getOrders,
  getOrderById,
  deleteOrder,
  updateOrder,
};

