sourcesContent:
const Sequelize = require("sequelize");
const db = require("../models");
const ResponseUser = require("../dtos/respone/user/responeuser");
const InsertUserRequest = require("../dtos/requests/user/insertUser")
const {UserRole} = require('../constants')
const argon2 = require("argon2")
const dotenv = require('dotenv') // đọc đến file .env
dotenv.config();
const jwt = require('jsonwebtoken')
const os = require('os');
const { getAvatarURL } = require('../helpers/imageHelper')



export async function RegisterUser(req, res) {
  const { email, phone, password } = req.body;

  console.log(UserRole);
  console.log(UserRole.USER);

  // phải có email hoặc phone
  if (!email && !phone) {
    return res.status(400).json({
      message: "Cần cung cấp email hoặc số điện thoại",
    });
  }

  const condition = {};

  if (email) condition.email = email;
  if (phone) condition.phone = phone;

  const existingUser = await db.User.findOne({
    where: condition,
  });

  if (existingUser) {
    return res.status(409).json({
      message: "Email hoặc số điện thoại đã tồn tại",
    });
  }

  const user = await db.User.create({
    email,
    phone,
    password,
    name: req.body.name,
    avatar: req.body.avatar,
    role: UserRole.USER,
  });

  return res.status(200).json({
    message: "Đăng ký user thành công",
    data: new ResponseUser(user),
  });
}

export async function Login(req, res) {
  const { email, phone, password } = req.body;

  // Validate that either email or phone is provided
  if (!email && !phone) {
    return res.status(400).json({
      message: "Cần cung cấp email hoặc số điện thoại",
    });
  }

  // Create dynamic search condition
  const condition = {};

  if (email) condition.email = email;
  if (phone) condition.phone = phone;

  // Find user
  const user = await db.User.findOne({
    where: condition,
  });

  if (!user) {
    return res.status(404).json({
      message: "tên hoặc mật khẩu không chính xác",
    });
  }

  // Verify password
  // tạm thời chưa hash
  const passwordValid = password === user.password;
  // nếu hash password :
  // const passwordValid = await argon2.verify(user.password, password)

  if (!passwordValid) {
    return res.status(401).json({
      message: "Mật khẩu không chính xác",
    });
  }

  // Generate JWT token
  const token = jwt.sign(
    { 
      id: user.id, 
      //role: user.role 
      iat: Math.floor(Date.now() / 1000) // thêm thời điểm tạo cho token
   },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_EXPIRATION }
  );

  // Return user information and token
  return res.status(200).json({
    message: "Đăng nhập thành công",
    data: {
      user: new ResponseUser(user),
      token,
    },
  });
}

export async function updateUser(req, res) {
  try {
    const { id } = req.params;

    const { name, avatar, oldPassword, newPassword } = req.body;

    if (req.user.id != id) {
      return res.status(403).json({
        message: "không được phép cập nhật thông tin của người khác",
      });
    }

    // tìm user
    const user = await db.User.findByPk(id);

    if (!user) {
      return res.status(404).json({
        message: "User không tồn tại",
      });
    }

    const updateData = {};

    // update name
    if (name !== undefined) {
      updateData.name = name;
    }

    // update avatar
    // update avatar
    if (avatar !== undefined) {
      updateData.avatar = getAvatarURL(avatar);
    }

    // đổi password
    if (oldPassword || newPassword) {
      if (!oldPassword || !newPassword) {
        return res.status(400).json({
          message: "Vui lòng nhập password cũ và password mới",
        });
      }

      // check password cũ
      if (oldPassword !== user.password) {
        return res.status(400).json({
          message: "Password cũ không đúng",
        });
      }

      // cập nhật password mới
      updateData.password = newPassword;
    }

    // update DB
    await db.User.update(updateData, {
      where: { id },
    });

    // lấy user mới
    const updatedUser = await db.User.findByPk(id);

    return res.status(200).json({
      message: "Cập nhật user thành công",
      data: updatedUser,
    });
  } catch (error) {
    return res.status(500).json({
      message: "Lỗi server",
      error: error.message,
    });
  }
}

