const Sequelize = require("sequelize");
const db = require("../models");
const OrderStatus = require("../constants")
const Op = Sequelize.Op;

async function getCarts(req, res) {
  const { page = 1 } = req.query;

  const pageSize = 5;
  const offset = (page - 1) * pageSize;

  const [carts, total] = await Promise.all([
    db.carts.findAll({
      limit: pageSize,
      offset,
      include: [
        {
          model: db.cart_items,
          as: "cart_items",
          include: [
            {
              model: db.products,
              as: "products",
            },
          ],
        },
      ],
    }),

    db.carts.count(),
  ]);

  return res.status(200).json({
    message: "Lấy danh sách giỏ hàng thành công",
    data: carts,
    currentPage: Number(page),
    totalPages: Math.ceil(total / pageSize),
    total,
  });
}

async function getCartById(req, res) {
  const { id } = req.params;

  const cart = await db.carts.findOne({
    where: { id },

    include: [
      {
        model: db.cart_items,
        as: "cart_items",

        include: [
          {
            model: db.products,
            as: "products",
          },
        ],
      },
    ],
  });
  if(!cart){
    return res.status(404).json({
      message: "giỏ hàng không tồn tại"
    })
  }

  return res.status(200).json({
    message: "Lấy giỏ hàng thành công",
    data: cart,
  });
}
async function insertCart(req, res) {
  const { id, user_id, session_id } = req.body;

  // chỉ tìm cart khi có id
  let existingCart = null;

  if (id) {
    existingCart = await db.carts.findOne({
      where: { id },
    });
  }

  // nếu tồn tại thì update
  if (existingCart) {
    existingCart.user_id = user_id;
    existingCart.session_id = session_id;

    await existingCart.save();

    return res.status(200).json({
      message: "Cập nhật giỏ hàng thành công",
      data: existingCart,
    });
  }
  // tạo mới cart
  const newCart = await db.carts.create({
    user_id,
    session_id,
  });

  return res.status(201).json({
    message: "Thêm giỏ hàng thành công",
    data: newCart,
  });
}

// Lấy danh sách cart (có phân trang)
async function checkoutCart(req, res) {
  const { cart_id, total, note } = req.body;

  const transaction = await db.sequelize.transaction();

  try {
    // 1. Lấy cart + cart_items + products
    const cart = await db.carts.findByPk(cart_id, {
      include: [
        {
          model: db.cart_items,
          as: "cart_items",
          include: [
            {
              model: db.products,
              as: "products",//join table
            },
          ],
        },
      ],
      transaction,
    });

    // 2. Check cart
    if (!cart) {
      await transaction.rollback();

      return res.status(404).json({
        message: "Giỏ hàng không tồn tại",
      });
    }

    // 3. Check cart rỗng
    if (!cart.cart_items || cart.cart_items.length === 0) {
      await transaction.rollback();

      return res.status(400).json({
        message: "Giỏ hàng trống",
      });
    }

    // 4. Check tồn kho
    for (const item of cart.cart_items) {
      if (!item.products) {
        await transaction.rollback();

        return res.status(404).json({
          message: `Sản phẩm ID ${item.product_id} không tồn tại`,
        });
      }

      if (item.products.quanity < item.quanity) {
        await transaction.rollback();

        return res.status(400).json({
          message: `Sản phẩm ${item.products.name} không đủ hàng`,
        });
      }
    }

    // 5. Tính total
    const finalTotal =
      total ??
      cart.cart_items.reduce((sum, item) => {
        return sum + item.quanity * item.products.price;
      }, 0);

    // 6. Tạo order
    const newOrder = await db.orders.create(
      {
        session_id: cart.session_id,
        user_id: cart.user_id,
        status: OrderStatus.PENDING,
        total: finalTotal,
        note: note || null,
      },
      { transaction },
    );

    // 7. Tạo order_detail
    const orderDetails = cart.cart_items.map((item) => ({
      order_id: newOrder.id,
      product_id: item.product_id,
      quanity: item.quanity,
      price: item.products.price,
    }));

    await db.order_detail.bulkCreate(orderDetails, {
      transaction,
    });

    // 8. Trừ kho
    for (const item of cart.cart_items) {
      await db.products.update(
        {
          quanity: item.products.quanity - item.quanity,
        },
        {
          where: {
            id: item.product_id,
          },
          transaction,
        },
      );
    }

    // 9. Xóa cart_items
    await db.cart_items.destroy({
      where: {
        cart_id: cart_id,
      },
      transaction,
    });

    // 10. Xóa cart
    await db.carts.destroy({
      where: {
        id: cart_id,
      },
      transaction,
    });

    // 11. Commit
    await transaction.commit();

    return res.status(200).json({
      message: "Thanh toán giỏ hàng thành công",
      data: {order_id: newOrder.id, order: newOrder}
    });
  } catch (error) {
    await transaction.rollback();

    console.log("detailed error:", error);

    return res.status(500).json({
      message: "Checkout thất bại",
      error: error.message,
    });
  }
}

// Xóa cart
async function deleteCart(req, res) {
  const { id } = req.params;

  const deleted = await db.carts.destroy({
    where: { id },
  });

  if (deleted) {
    return res.status(200).json({
      message: "Xóa giỏ hàng thành công",
    });
  }

  return res.status(404).json({
    message: "Giỏ hàng không tồn tại",
  });
}

module.exports = {
  getCarts,
  getCartById,
  insertCart,
  deleteCart,
  checkoutCart,
};

