const db = require('../models');
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET;


async function getUserFromToken(req, res) {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      return res.status(401).json({
        message: "Không có token được cung cấp",
      });
    }

    const token = authHeader.split(" ")[1];

    if (!token) {
      return res.status(401).json({
        message: "Token không hợp lệ",
      });
    }

    const decoded = jwt.verify(token, JWT_SECRET);
    //kiểm tra xem token có được tạo sau khi đổi mật khẩu không
    const user = await db.User.findByPk(decoded.id);

    if (!user) {
      return res.status(404).json({
        message: "Người dùng không tồn tại",
      });
    }
    if (
      user.password_changed_at &&//issue at = iat
      decoded.iat < new Date(user.password_changed_at).getTime() / 1000
    ) {
      return res.status(401).json({
        message: "token không hợp lệ do mật khẩu đã thay đổi",
      });
    }


    return user;
  } catch (error) {
    return res.status(401).json({
      message: "Token không hợp lệ hoặc đã hết hạn",
      error: error.toString(),
    });
  }
}
module.exports = {
    getUserFromToken
};

