"use strict";
const { Model } = require("sequelize");

module.exports = (sequelize, DataTypes) => {
  class order_detail extends Model {
    /**
     * Helper method for defining associations.
     * This method is not a part of Sequelize lifecycle.
     * The `models/index` file will call this method automatically.
     */
    static associate(models) {
      // 👉 ĐÃ SỬA: Gọi trực tiếp tên model gốc theo đúng nhật ký CLI của bạn (không cần if phòng thủ)
      order_detail.belongsTo(models.orders, {
        foreignKey: "order_id",
        as: "orders",
      });

      order_detail.belongsTo(models.products, {
        foreignKey: "product_id",
        as: "products",
      });
    }
  }

  order_detail.init(
    {
      order_id: DataTypes.INTEGER,
      product_id: DataTypes.INTEGER,
      quantity: DataTypes.INTEGER,
      price: DataTypes.INTEGER,
    },
    {
      sequelize,
      modelName: "order-detail", // 👈 ĐÃ SỬA: Khớp 100% với lệnh npx sequelize-cli model:generate --name order-detail
      tableName: "order_detail", // Giữ nguyên số ít theo đúng ảnh chụp database thực tế của bạn
      timestamps: true, // Bật bộ đếm thời gian
      underscored: true, // Ép Sequelize map theo dạng gạch dưới _
      createdAt: "created_at", // Khóa kép: Ép bắt buộc map trúng cột này dưới MySQL
      updatedAt: "updated_at",
    },
  );

  return order_detail;
};

